/**
 * @description: User Portal Header - renders the sidebar navbar
 * @author: Institute User Portal
 */
import React from 'react';
import NavbarUser from './Navbar';

function Header({ onOpenHomework }) {
  return <NavbarUser onOpenHomework={onOpenHomework} />;
}

export default Header;
